import{serializeInputSchema,serializeOutputSchema}from"#tools/schema.js";import{connectionToolName}from"#connections/ownership.js";import{renderToolSignature}from"#tools/signature.js";function entrySignature(e,t=serializeInputSchema(e.inputSchema)){return renderToolSignature({inputSchema:t,name:e.name,outputSchema:serializeOutputSchema(e.outputSchema)})}function connectionToolSignature(e,t){return renderToolSignature({inputSchema:t.inputSchema,name:connectionToolName(e.connectionName,t.name),outputSchema:t.outputSchema})}export{connectionToolSignature,entrySignature};